<script setup lang="ts">
import { ref,onMounted } from 'vue'
import CurrencyPicker from '../../components/CurrencyPicker.vue'
import { Save,Upload } from 'lucide-vue-next'
import { api,json } from '../../api/client'
import { useRouter } from 'vue-router'
import { useAuth } from '../../stores/auth'
import type { Business } from '../../types'
const router=useRouter(),auth=useAuth(),form=ref<Business|null>(null),error=ref(''),success=ref(''),busy=ref(false),uploading=ref(false),logoBroken=ref(false),changeNumbers=ref(false),numberMode=ref('next'),invoiceStart=ref('1'),quotationStart=ref('1')
onMounted(async()=>{try{form.value=await api<Business>('/business');form.value.bank_accounts??=[];invoiceStart.value=String(form.value.next_invoice_number||1).padStart(form.value.invoice_padding||4,'0');quotationStart.value=String(form.value.next_quotation_number||1).padStart(form.value.quotation_padding||4,'0')}catch(e){error.value=(e as Error).message}})
function starting(event:Event,kind:'invoice'|'quotation'){const value=(event.target as HTMLInputElement).value;if(!form.value)return;if(kind==='invoice'){invoiceStart.value=value;if(/^0\d+$/.test(value))form.value.invoice_padding=value.length}else{quotationStart.value=value;if(/^0\d+$/.test(value))form.value.quotation_padding=value.length}}
function preview(kind:'invoice'|'quotation'){if(!form.value)return '';const f=form.value,start=kind==='invoice'?invoiceStart.value:quotationStart.value,padding=(kind==='invoice'?f.invoice_padding:f.quotation_padding)||4,counter=changeNumbers.value?Number(start)+(numberMode.value==='last'?1:0):(kind==='invoice'?f.next_invoice_number:f.next_quotation_number)||1;return (kind==='invoice'?f.invoice_prefix:(f.quotation_prefix||'QUO'))+((kind==='invoice'?f.invoice_separator:f.quotation_separator)??'-')+String(counter).padStart(padding,'0')}
async function save(){busy.value=true;error.value='';try{form.value=await api<Business>('/business',json('PUT',{...form.value,next_invoice_number:changeNumbers.value?Number(invoiceStart.value)+(numberMode.value==='last'?1:0):undefined,next_quotation_number:changeNumbers.value?Number(quotationStart.value)+(numberMode.value==='last'?1:0):undefined}));if(auth.user)auth.user.business=form.value;changeNumbers.value=false;invoiceStart.value=String(form.value.next_invoice_number||1).padStart(form.value.invoice_padding||4,'0');quotationStart.value=String(form.value.next_quotation_number||1).padStart(form.value.quotation_padding||4,'0');success.value='Your business settings are saved.'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function removeBusiness(){
 const name=prompt('Permanently delete this business and all its invoices, clients, payments and accounts? Type the exact business name to confirm.')
 if(name===null)return
 if(name!==form.value?.name){error.value='Business name does not match.';return}
 busy.value=true
 try{await api('/business',json('DELETE',{business_name:name}));localStorage.removeItem('invoice_token');auth.user=null;router.push('/login')}catch(e){error.value=(e as Error).message}finally{busy.value=false}
}
async function logo(event:Event){error.value='';success.value='';logoBroken.value=false;const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;const body=new FormData();body.append('logo',file);uploading.value=true;try{form.value=await api<Business>('/business/logo',{method:'POST',body});if(auth.user)auth.user.business=form.value;success.value='Logo updated.'}catch(e){error.value=(e as Error).message}finally{uploading.value=false;(event.target as HTMLInputElement).value=''}}
</script>
<template><div class="page-heading"><div><span class="eyebrow">MAKE IT YOURS</span><h1>Business settings<span class="heading-dot">.</span></h1><p class="muted">Your details. Your brand. On every invoice.</p></div></div><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="success" class="success" role="status">{{ success }}</p><form v-if="form" @submit.prevent="save" class="editor-grid"><div><section class="panel form-panel"><h2>Business details</h2><label>Business name<input v-model="form.name" required></label><div class="form-grid"><label>Billing email<input v-model="form.email" type="email"></label><label>Phone number<input v-model="form.phone" type="tel" placeholder="+2348012345678"><small class="muted">Use + and your country calling code. Currency does not change your phone number. Nigerian local numbers are also accepted.</small></label></div><label>Address<textarea v-model="form.address" rows="2"/></label></section><section class="panel form-panel spaced"><h2>Invoice defaults</h2><div class="form-grid"><label>Invoice prefix<input v-model="form.invoice_prefix" required maxlength="15"></label><label>Default tax (%)<input v-model.number="form.default_tax_percent" type="number" min="0" max="100" step=".01" required></label><label>Default currency<CurrencyPicker v-model="form.currency"/></label></div><h2 class="spaced">Document numbering</h2><p class="muted">Existing document numbers stay unchanged. New numbers cannot move backwards. Prefix + separator + padded counter forms the number, for example INV/000125.</p><div class="form-grid"><label>Invoice separator<select v-model="form.invoice_separator"><option value="-">Hyphen</option><option value="/">Slash</option><option value="">None</option></select></label><label>Invoice digits<input v-model.number="form.invoice_padding" type="number" min="1" max="10"></label><label>Quotation prefix<input v-model="form.quotation_prefix" maxlength="15"></label><label>Quotation separator<select v-model="form.quotation_separator"><option value="-">Hyphen</option><option value="/">Slash</option><option value="">None</option></select></label><label>Quotation digits<input v-model.number="form.quotation_padding" type="number" min="1" max="10"></label></div><p class="muted">Next counters: invoice {{ form.next_invoice_number }}, quotation {{ form.next_quotation_number }}.</p><label><input type="checkbox" v-model="changeNumbers"> Set starting counters</label><div v-if="changeNumbers" class="form-grid"><label>Value represents<select v-model="numberMode"><option value="next">Next number to issue</option><option value="last">Last number already used (adds 1)</option></select></label><label>Invoice counter<input :value="invoiceStart" @input="starting($event,'invoice')" type="text" inputmode="numeric" pattern="[0-9]{1,10}" maxlength="10" required></label><label>Quotation counter<input :value="quotationStart" @input="starting($event,'quotation')" type="text" inputmode="numeric" pattern="[0-9]{1,10}" maxlength="10" required></label></div><p class="muted" aria-live="polite">Next invoice: {{ preview('invoice') }} · Next quotation: {{ preview('quotation') }}</p><p class="muted">Digits means minimum numeric width: 112 becomes 000112 at 6 digits, or 00112 at 5 digits. Leading zeros in starting counters set the width automatically; numbers are never truncated.</p><h2 class="spaced">Bank accounts (optional)</h2><p class="muted">Enter receiving account details manually. Choose which documents display each account. Never enter PINs, passwords or card security codes.</p><section v-for="(account,index) in form.bank_accounts" :key="index" class="panel form-panel spaced"><div class="form-grid"><label>Bank name<input v-model="account.bank_name" maxlength="150"></label><label>Account holder<input v-model="account.account_name" maxlength="150"></label><label>Account number / IBAN<input v-model="account.account_number" maxlength="100"></label><label>SWIFT / routing code (optional)<input v-model="account.routing_code" maxlength="100"></label></div><label>Additional details<textarea v-model="account.details" maxlength="1000"/></label><label><input type="checkbox" v-model="account.show_on_invoice"> Show on invoices</label><label><input type="checkbox" v-model="account.show_on_quotation"> Show on quotations</label><button type="button" class="button secondary" @click="form.bank_accounts.splice(index,1)">Remove account</button></section><button type="button" class="button secondary spaced" :disabled="form.bank_accounts.length>=10" @click="form.bank_accounts.push({bank_name:'',account_name:'',account_number:'',routing_code:'',details:'',show_on_invoice:true,show_on_quotation:true})">Add bank account</button><label class="spaced">Payment instructions<textarea v-model="form.payment_instructions" rows="4" placeholder="Bank name, account number, and account holder"/></label><div class="form-actions"><button class="button primary" :disabled="busy"><Save :size="16"/>{{ busy?'Saving…':'Save settings' }}</button></div></section></div><aside><section class="panel form-panel"><span class="eyebrow">YOUR BRAND</span><h2>A familiar face.</h2><div class="logo-preview"><img v-if="form.logo_url&&!logoBroken" :src="form.logo_url" alt="Business logo" @error="logoBroken=true"><span v-else>{{ form.name.slice(0,2).toUpperCase() }}</span></div><p v-if="logoBroken" class="error">The saved logo could not be loaded. Try uploading it again.</p><label class="button secondary upload-label"><Upload :size="16"/>{{ uploading?'Uploading...':'Upload logo' }}<input type="file" accept="image/png,image/jpeg" :disabled="uploading" @change="logo"></label><small class="muted">PNG or JPG, up to 1 MB.</small><label class="spaced">Brand colour<div class="color-control"><input v-model="form.brand_color" type="color"><input v-model="form.brand_color" pattern="#[a-fA-F0-9]{6}" required></div></label><p class="muted">Used on your invoice PDF and public invoice page.</p></section><section v-if="auth.user?.role==='owner'" class="panel form-panel spaced"><h2>Delete business</h2><p class="muted">Permanently removes this workspace, all invoices, clients, payments, and team accounts.</p><button type="button" class="button secondary danger-text wide spaced" :disabled="busy" @click="removeBusiness">Delete business permanently</button></section></aside></form></template>